missing = [p for p in paths if p not in R]
extra = [p for p in R if p not in paths]
with open(sys.argv[2], 'w') as o:
    o.write('| # | File | Category | Role | Status |\n|---|---|---|---|---|\n')
    for i, p in enumerate(paths, 1):
        c, role, st = R.get(p, ('?', '?', '?'))
        o.write('| %d | `%s` | %s | %s | %s |\n' % (i, p, c, role.replace('|', '/'), st))
print('rows', len(paths), 'missing', missing, 'extra', extra)
